export type SetBetRequest = {
    /**
     * Цена ставки (> 0)
     */
    price: number;
};

/**
 * Торговый статус пользователя в аукционе:
 * - `NotParticipating` — не участвует (1)
 * - `Leading` — лидирует (2)
 * - `Losing` — перебит (3)
 * - `Winner` — победитель (4)
 * - `Confirmed` — подтверждён (5)
 * - `Unknown` — неизвестный статус
 */
export type TradingStatus = 'NotParticipating' | 'Leading' | 'Losing' | 'OnPending' | 'Confirmed' | 'ChoosingWinner' | 'Winner' | 'Accepted' | 'Unknown';

/**
 * Ошибка по конкретному полю запроса
 */
export type ValidationError = {
    /**
     * Путь к полю (snake_case, вложенные — через точку)
     */
    field: string;
    message: string;
    /**
     * Машиночитаемый код нарушения
     */
    code?: string | null;
};

/**
 * Ошибка валидации входных данных (422). Отличается от бизнес-ошибки кодом `validation_failed` и наличием `errors[]`.
 */
export type ValidationProblem = {
    code: string;
    title: string;
    message: string;
    trace_id?: string | null;
    errors: Array<ValidationError>;
};

export type ListAuctionsData = {
    body?: AuctionListRequest;
    path?: never;
    query?: never;
    url: '/auctions/list';
};

export type ListAuctionsErrors = {
    /**
     * Не авторизован (отсутствует или недействителен Bearer-токен)
     */
    401: ProblemDetail;
    /**
     * Ошибка валидации входных данных
     */
    422: ValidationProblem;
    /**
     * Временная недоступность upstream (перегрузка, соединение не установлено)
     */
    503: ProblemDetail;
};

export type ListAuctionsError = ListAuctionsErrors[keyof ListAuctionsErrors];

export type ListAuctionsResponses = {
    /**
     * Успешный ответ
     */
    200: AuctionListResponseBase;
};

export type ListAuctionsResponse = ListAuctionsResponses[keyof ListAuctionsResponses];

export type GetAuctionData = {
    body?: never;
    path: {
        auctionUuid: string;
    };
    query?: never;
    url: '/auctions/{auctionUuid}';
};

export type GetAuctionErrors = {
    /**
     * Не авторизован (отсутствует или недействителен Bearer-токен)
     */
    401: ProblemDetail;
    /**
     * Ресурс не найден
     */
    404: ProblemDetail;
    /**
     * Временная недоступность upstream (перегрузка, соединение не установлено)
     */
    503: ProblemDetail;
};

export type GetAuctionError = GetAuctionErrors[keyof GetAuctionErrors];

export type GetAuctionResponses = {
    /**
     * Успешный ответ
     */
    200: AuctionShowResponse;
};

export type GetAuctionResponse = GetAuctionResponses[keyof GetAuctionResponses];

